head.b:skin:
@import url('https://fonts.googleapis.com/css2?family=Cinzel+Decorative:wght@400;700&family=Inter:wght@300;400;500;600&display=swap');

:root{--bg:#0a0a0a;--panel:#0f0f0f;--card:#141414;--text:#e5e5e5;--muted:rgba(255,255,255,.58);--faint:rgba(255,255,255,.28);--red:#ff2a2a;}
*{box-sizing:border-box}
html{scroll-behavior:smooth;background:var(--bg)}
body{margin:0;background:var(--bg);color:var(--text);font-family:Inter,Arial,sans-serif;font-weight:300;-webkit-font-smoothing:antialiased}
a{color:inherit;text-decoration:none}
img{display:block;max-width:100%;height:auto}
button,a{cursor:pointer}
.serif{font-family:'Cinzel Decorative',Georgia,serif}
.wrap{width:min(1600px,100%);margin:0 auto;padding-left:40px;padding-right:40px}
.nav{position:fixed;z-index:50;top:0;left:0;right:0;padding:28px 40px;display:flex;justify-content:space-between;align-items:center;color:#fff;mix-blend-mode:difference}
.micro{font-size:11px;letter-spacing:.28em;text-transform:uppercase}
.hero{position:relative;min-height:100svh;display:flex;align-items:flex-end;overflow:hidden}
.hero-image{position:absolute;inset:0;width:100%;height:100%;object-fit:cover}
.hero-shade{position:absolute;inset:0;background:rgba(10,10,10,.38)}
.hero-gradient{position:absolute;inset:0;background:linear-gradient(to top,#0a0a0a 0%,rgba(10,10,10,.45) 42%,transparent 82%)}
.hero-content{position:relative;z-index:2;width:min(720px,100%);padding:0 0 80px}
.eyebrow{color:rgba(255,255,255,.48);margin:0 0 28px}
h1,h2,h3,p{margin-top:0}
.hero-title{font-size:clamp(72px,10vw,112px);line-height:.86;letter-spacing:-.045em;font-weight:700;margin:0;color:#fff}
.hero-title em{font-weight:400;color:#fff;margin-left:.08em}
.hero-meta{display:flex;gap:40px;align-items:flex-end;margin-top:40px}
.hero-sub{font-size:20px;line-height:1.3;color:rgba(255,255,255,.9);margin:0}
.hero-status{font-size:12px;letter-spacing:.15em;text-transform:uppercase;color:rgba(255,255,255,.38);margin-top:8px}
.pill{display:inline-flex;align-items:center;justify-content:center;height:48px;padding:0 28px;border:1px solid rgba(255,255,255,.15);border-radius:999px;background:rgba(255,255,255,.04);font-size:11px;letter-spacing:.2em;text-transform:uppercase;color:#fff;transition:.2s}
.pill:hover{border-color:rgba(255,255,255,.4);background:rgba(255,255,255,.08)}
.red-line{height:1px;background:linear-gradient(to right,transparent,rgba(255,42,42,.5),transparent)}
.section{padding:128px 0;background:var(--bg)}
.section.alt{background:var(--panel);border-top:1px solid rgba(255,255,255,.06);border-bottom:1px solid rgba(255,255,255,.06)}
.two-col{display:grid;grid-template-columns:5fr 7fr;gap:80px;align-items:start}
.photo-tall{aspect-ratio:4/5.2;overflow:hidden;background:#171717}
.photo-tall img{width:100%;height:100%;object-fit:cover}
.caption{display:flex;justify-content:space-between;align-items:center;margin-top:16px;color:rgba(255,255,255,.3);font-size:10px;letter-spacing:.2em;text-transform:uppercase}
.caption i{display:block;width:32px;height:1px;background:rgba(255,42,42,.6)}
.copy{max-width:560px;padding-left:40px}
.label{font-size:11px;letter-spacing:.3em;text-transform:uppercase;color:var(--red);margin-bottom:30px}
.headline{font-size:clamp(32px,4vw,54px);line-height:1.05;letter-spacing:-.025em;font-weight:400;color:#fff;margin-bottom:32px}
.headline span{color:rgba(255,255,255,.4)}
.bodycopy{font-size:15px;line-height:1.8;color:var(--muted)}
.bodycopy p{margin:0 0 20px}
.bodycopy strong{color:rgba(255,255,255,.9);font-weight:400}
.facts{display:flex;gap:40px;border-top:1px solid rgba(255,255,255,.07);margin-top:48px;padding-top:30px}
.fact-label{font-size:11px;letter-spacing:.2em;text-transform:uppercase;color:rgba(255,255,255,.3);margin-bottom:6px}
.fact-value{font-size:13px;color:rgba(255,255,255,.8)}
.release{display:flex;gap:80px;align-items:center}
.cover{flex:0 0 300px;width:300px;height:300px;overflow:hidden;box-shadow:0 20px 80px rgba(0,0,0,.6)}
.cover img{width:100%;height:100%;object-fit:cover}
.release-info{width:min(560px,100%)}
.release-title{display:flex;align-items:baseline;gap:16px;margin-bottom:24px}
.release-title h3{font-size:34px;line-height:1;margin:0;font-weight:400;color:#fff}
.release-title span{font-size:11px;letter-spacing:.2em;text-transform:uppercase;color:rgba(255,255,255,.3)}
.release-card{background:var(--card);border:1px solid rgba(255,255,255,.06);border-radius:18px;padding:28px}
.release-card p{font-size:12px;line-height:1.7;color:rgba(255,255,255,.32);margin:20px 0 0}
.audio{width:100%;height:42px;filter:invert(1);opacity:.82}
.tags{display:flex;flex-wrap:wrap;gap:10px;margin-top:24px;padding-top:22px;border-top:1px solid rgba(255,255,255,.06)}
.tag{padding:7px 12px;border-radius:999px;border:1px solid rgba(255,255,255,.06);background:rgba(255,255,255,.04);font-size:10px;letter-spacing:.2em;text-transform:uppercase;color:rgba(255,255,255,.4)}
.tag.red{border-color:rgba(255,42,42,.2);background:rgba(255,42,42,.1);color:rgba(255,42,42,.8)}
.portfolio-head{display:flex;justify-content:space-between;align-items:flex-end;margin-bottom:48px}
.portfolio-title{font-size:clamp(36px,5vw,62px);line-height:.95;font-weight:400;color:#fff;margin:0}
.portfolio-title span{color:rgba(255,255,255,.3)}
.posts-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:24px}
.post-card{background:#111;border:1px solid rgba(255,255,255,.06);transition:.25s;overflow:hidden}
.post-card:hover{border-color:rgba(255,255,255,.18);transform:translateY(-2px)}
.post-thumb{aspect-ratio:4/3;background:#171717;overflow:hidden}
.post-thumb img{width:100%;height:100%;object-fit:cover;transition:.4s}
.post-card:hover .post-thumb img{transform:scale(1.025)}
.post-body{padding:24px}
.post-date{font-size:10px;letter-spacing:.18em;text-transform:uppercase;color:rgba(255,255,255,.3);margin-bottom:12px}
.post-title{font-size:24px;line-height:1.1;font-weight:400;color:#fff;margin:0 0 14px}
.post-snippet{font-size:13px;line-height:1.65;color:rgba(255,255,255,.5);margin:0}
.post-more{display:inline-block;margin-top:20px;font-size:10px;letter-spacing:.2em;text-transform:uppercase;color:rgba(255,255,255,.65)}
.studio-grid{display:grid;grid-template-columns:5fr 7fr;gap:80px}
.studio-copy{max-width:560px;padding-left:40px}
.studio-copy .lead{font-size:17px;line-height:1.6;color:rgba(255,255,255,.85)}
.actions{display:flex;gap:16px;flex-wrap:wrap;margin-top:40px}
.button{display:inline-flex;align-items:center;justify-content:center;height:48px;padding:0 28px;border-radius:999px;font-size:11px;letter-spacing:.2em;text-transform:uppercase}
.button.primary{background:#fff;color:#000}.button.primary:hover{background:#eee}
.button.secondary{border:1px solid rgba(255,255,255,.15);color:rgba(255,255,255,.8)}.button.secondary:hover{border-color:rgba(255,255,255,.3);color:#fff}
footer{padding:32px 0 44px;border-top:1px solid rgba(255,255,255,.06);display:flex;justify-content:space-between;gap:20px;color:rgba(255,255,255,.2);font-size:10px;letter-spacing:.2em;text-transform:uppercase}
.mobile-only{display:none}#utility{display:none}
@media(max-width:900px){.wrap{padding-left:24px;padding-right:24px}.nav{padding:22px 24px}.section{padding:88px 0}.two-col,.studio-grid{grid-template-columns:1fr;gap:48px}.copy,.studio-copy{padding-left:0}.release{flex-direction:column;align-items:flex-start;gap:40px}.posts-grid{grid-template-columns:1fr 1fr}.hero-content{padding-bottom:56px}.hero-meta{flex-direction:column;align-items:flex-start;gap:24px}}
@media(max-width:600px){.posts-grid{grid-template-columns:1fr}.cover{width:100%;height:auto;aspect-ratio:1}.hero-title{font-size:22vw}.hero-sub{font-size:18px}.facts{gap:24px;flex-wrap:wrap}footer{flex-direction:column}.micro{font-size:10px}}
